{"yol":"indirim.js","icerik":"export function indirimUygula(fiyat, yuzde) {
  if (yuzde < 0 || yuzde > 100) {
    throw new RangeError('İndirim yüzdesi 0 ile 100 arasında olmalıdır')
  }

  const indirimliFiyat = fiyat * (1 - yuzde / 100)
  return Math.round(indirimliFiyat)
}"}

